const cinemaReady=setInterval(()=>{if(!nodes||!layout)return;clearInterval(cinemaReady);mount();renderObjects();},100);

// Profile post collections: board placements reference the existing source nodes.
const groupPostLookup=id=>nodes.find(n=>n.id===id)||layout.nodes.find(n=>n.id===id);
function profileMembers(p){return (p.memberIds||[]).map(groupPostLookup).filter(Boolean);}
function groupedOutput(p){return nodes.find(n=>n.outputProfile===p.id||n.id==='profile-stories-'+p.id);}
function createProfileOutput(p){try{const deleted=JSON.parse(localStorage.getItem('rednote-deleted-nodes-v1')||'[]');localStorage.setItem('rednote-deleted-nodes-v1',JSON.stringify(deleted.filter(id=>id!=='profile-stories-'+p.id)));}catch{}const out={id:'profile-stories-'+p.id,kind:'output',uiCreated:true,outputProfile:p.id,title:p.title+' · Stories',x:p.x,y:p.y+p.h+120,w:p.w,h:370,story:{status:'local_authored_drafts',draft:'',stories:[]},actor:structuredClone(p.actor||{}),override:{enabled:false,influence:.5}};for(const post of profileMembers(p)){const old=nodes.find(v=>v.kind==='output'&&layout.edges.some(e=>e[0]===post.id&&e[1]===v.id));if(old?.story?.draft)out.story.stories.push({id:'legacy-'+old.id,title:old.title,text:old.story.draft});}nodes.push(out);layout.edges.push([p.id,out.id,'Selected posts → multiple stories',{direction:'forward',active:true}]);sourcePositions[out.id]=[out.x,out.y,out.w,out.h];return out;}
