// The original actor is the visual root of the authored branches. Keep the
// existing handle, media button, JSON controls, actions, and real port elements.
const cardBeforeMasterProtagonist=card;
card=function(n){
 cardBeforeMasterProtagonist(n);
 if(n.id!=='actor')return;
 const node=document.getElementById(n.id);
 const handle=node?.querySelector(':scope > .handle');
 const portrait=node?.querySelector(':scope > .poster');
 const subtitle=node?.querySelector(':scope > .subtitle');
 const actions=node?.querySelector(':scope > .actions');
 if(!node||!handle||!portrait||!actions)return;
 node.classList.add('master-protagonist');
 node.setAttribute('aria-label','Rainee · original protagonist and master actor profile');
 const crest=el('span','master-crest');crest.setAttribute('aria-hidden','true');crest.textContent='R';
 handle.prepend(crest);
 const type=handle.querySelector('.type');if(type)type.textContent='ORIGIN PROFILE · MASTER PROTAGONIST';
 const title=handle.querySelector('b');if(title)title.textContent='Rainee';
 handle.append(el('span','master-drag-hint','DRAG HEADER · MOVE ACTOR TREE'));
 const artwork=el('div','master-artwork');
 artwork.append(portrait,el('div','master-art-caption','RAINEE 01  /  ORIGINAL ACTOR'));
 const body=el('div','master-body');body.append(handle);
 if(subtitle)body.append(subtitle);
 const facts=el('div','master-facts');
 const identity=el('div','master-fact');identity.append(el('span','','ACTOR ID'),el('strong','',n.actor?.fictional_actor_ref||'rainee.base'));
 const branch=el('div','master-fact');branch.append(el('span','','SOURCE BRANCH'),el('strong','',n.branch||'main_lingzi'));
 facts.append(identity,branch);body.append(facts);
 const lineage=el('div','master-lineage');
 lineage.append(el('span','master-lineage-label','ORIGINAL CHARACTER'),el('span','master-lineage-arrow','→'),el('span','master-lineage-label','ALTERNATIVE PATHS'));
 body.append(lineage);
 const jsonRow=el('div','master-json-controls');
 node.querySelectorAll(':scope > .json-preview').forEach(button=>jsonRow.append(button));
 body.append(jsonRow,actions);
 const shell=el('div','master-shell');shell.append(artwork,body);node.prepend(shell);
};
